-- Frozen car_rental dataset. Generated once from the original
-- generative seed, then committed verbatim so that every engine and
-- every PostgreSQL version loads byte-identical rows. random()/setseed()
-- are deliberately not used here: PostgreSQL 16 changed its PRNG, so a
-- generative seed yields different data on PG15 vs PG16 and the
-- cross-engine comparison would be confounded by the data itself.


-- locations (10 rows)

-- vehicle_categories (5 rows)

-- clients (600 rows)

-- employees (40 rows)

-- vehicles (80 rows)

-- reservations (3000 rows)

-- payments (2691 rows)

-- maintenance_records (400 rows)

-- reviews (1200 rows)

-- Resync identity columns past the explicit ids inserted above
ALTER TABLE car_rental.locations MODIFY (id GENERATED BY DEFAULT AS IDENTITY (START WITH LIMIT VALUE));
ALTER TABLE car_rental.vehicle_categories MODIFY (id GENERATED BY DEFAULT AS IDENTITY (START WITH LIMIT VALUE));
ALTER TABLE car_rental.clients MODIFY (id GENERATED BY DEFAULT AS IDENTITY (START WITH LIMIT VALUE));
ALTER TABLE car_rental.employees MODIFY (id GENERATED BY DEFAULT AS IDENTITY (START WITH LIMIT VALUE));
ALTER TABLE car_rental.vehicles MODIFY (id GENERATED BY DEFAULT AS IDENTITY (START WITH LIMIT VALUE));
ALTER TABLE car_rental.reservations MODIFY (id GENERATED BY DEFAULT AS IDENTITY (START WITH LIMIT VALUE));
ALTER TABLE car_rental.payments MODIFY (id GENERATED BY DEFAULT AS IDENTITY (START WITH LIMIT VALUE));
ALTER TABLE car_rental.maintenance_records MODIFY (id GENERATED BY DEFAULT AS IDENTITY (START WITH LIMIT VALUE));
ALTER TABLE car_rental.reviews MODIFY (id GENERATED BY DEFAULT AS IDENTITY (START WITH LIMIT VALUE));
COMMIT;
